import cmath
import numpy as np

def char_roots(a, b, c):
    """Roots of a r^2 + b r + c = 0, sorted by real part, then imaginary part."""
    d = b * b - 4 * a * c
    if d >= 0:
        s = d ** 0.5
        return sorted([(-b - s) / (2 * a), (-b + s) / (2 * a)])
    s = cmath.sqrt(d)
    return sorted([(-b - s) / (2 * a), (-b + s) / (2 * a)], key=lambda z: (z.real, z.imag))

def solve_const_coeff(a, b, c, y0, v0, t):
    """y(t) for a y'' + b y' + c y = 0 with y(0) = y0, y'(0) = v0."""
    t = np.asarray(t, dtype=float)
    d = b * b - 4 * a * c
    if abs(d) < 1e-12:
        r = -b / (2 * a)
        return (y0 + (v0 - r * y0) * t) * np.exp(r * t)
    if d > 0:
        r1, r2 = char_roots(a, b, c)
        c2 = (v0 - r1 * y0) / (r2 - r1)
        return (y0 - c2) * np.exp(r1 * t) + c2 * np.exp(r2 * t)
    al, be = -b / (2 * a), (-d) ** 0.5 / (2 * a)
    return np.exp(al * t) * (y0 * np.cos(be * t) + (v0 - al * y0) / be * np.sin(be * t))

